public sealed class FornecedorRepository(NpgsqlConnectionFactory factory):IFornecedorRepository
{
 public async Task<PagedResult<FornecedorResumo>> ListarAsync(Guid t,FornecedorFiltro f,CancellationToken ct){var p=Math.Max(1,f.Pagina);var s=Math.Clamp(f.Tamanho,1,100);const string q="select count(*) from sigov.compras_empresarial_fornecedor where tenant_id=@t and not is_deleted and (@status is null or status=@status) and (@busca is null or razao_social ilike @term or nome_fantasia ilike @term or codigo ilike @term);select id,codigo,razao_social RazaoSocial,nome_fantasia NomeFantasia,documento_mascarado DocumentoMascarado,status,score,version from sigov.compras_empresarial_fornecedor where tenant_id=@t and not is_deleted and (@status is null or status=@status) and (@busca is null or razao_social ilike @term or nome_fantasia ilike @term or codigo ilike @term) order by razao_social offset @off limit @s";await using var c=factory.CreateConnection();using var m=await c.QueryMultipleAsync(new CommandDefinition(q,new{t,status=string.IsNullOrWhiteSpace(f.Status)?null:f.Status.ToUpperInvariant(),busca=string.IsNullOrWhiteSpace(f.Busca)?null:f.Busca,term=$"%{f.Busca}%",off=(p-1)*s,s},cancellationToken:ct));var n=await m.ReadSingleAsync<long>();return new((await m.ReadAsync<FornecedorResumo>()).AsList(),p,s,n);}
 public async Task<FornecedorResumo?> ObterAsync(Guid t,Guid id,CancellationToken ct){const string q="select id,codigo,razao_social RazaoSocial,nome_fantasia NomeFantasia,documento_mascarado DocumentoMascarado,status,score,version from sigov.compras_empresarial_fornecedor where tenant_id=@t and id=@id and not is_deleted";await using var c=factory.CreateConnection();return await c.QuerySingleOrDefaultAsync<FornecedorResumo>(new CommandDefinition(q,new{t,id},cancellationToken:ct));}
 public async Task<Guid> CriarAsync(ComprasContext x,CriarFornecedorRequest r,string key,CancellationToken ct){await using var c=factory.CreateConnection();await c.OpenAsync(ct);await using var tx=await c.BeginTransactionAsync(ct);await c.ExecuteAsync(new CommandDefinition("select pg_advisory_xact_lock(hashtextextended(@chaveLock,0))",new{chaveLock=$"{x.TenantId:D}|FORNECEDOR|CRIAR|{key}"},tx,cancellationToken:ct));var hash=HashPayload(r);var anterior=await c.QuerySingleOrDefaultAsync<IdemComHash>(new CommandDefinition("select recurso_id RecursoId,request_hash RequestHash from sigov.compras_empresarial_idempotencia where tenant_id=@t and operacao='FORNECEDOR_CRIAR' and chave=@key",new{t=x.TenantId,key},tx,cancellationToken:ct));if(anterior is not null){if(anterior.RequestHash is not null && anterior.RequestHash!=hash)throw new ComprasConcurrencyException("A chave de idempotência já foi usada com conteúdo diferente.");await tx.CommitAsync(ct);return anterior.RecursoId;}var id=Guid.NewGuid();var codigo=await Next(c,tx,x.TenantId,"FORNECEDOR","FOR",ct);const string sql="insert into sigov.compras_empresarial_fornecedor(id,tenant_id,codigo,nome,tipo_pessoa,documento_hash,documento_mascarado,razao_social,nome_fantasia,categoria,porte,condicao_pagamento,prazo_medio,observacoes,created_by,updated_by,correlation_id) values(@id,@t,@codigo,@RazaoSocial,upper(@TipoPessoa),encode(public.digest(regexp_replace(@Documento,'[^0-9]','','g'),'sha256'),'hex'),case when length(regexp_replace(@Documento,'[^0-9]','','g'))=14 then '***.***.***/' || substring(regexp_replace(@Documento,'[^0-9]','','g') from 9 for 4) || '-**' else '***.***.' || substring(regexp_replace(@Documento,'[^0-9]','','g') from 7 for 3) || '-**' end,@RazaoSocial,@NomeFantasia,@Categoria,@Porte,@CondicaoPagamento,@PrazoMedio,@Observacoes,@us,@us,@corr);insert into sigov.compras_empresarial_historico(tenant_id,aggregate_type,aggregate_id,acao,created_by,correlation_id) values(@t,'FORNECEDOR',@id,'CRIADO',@us,@corr);insert into sigov.compras_empresarial_idempotencia(tenant_id,operacao,chave,recurso_id,request_hash) values(@t,'FORNECEDOR_CRIAR',@key,@id,@hash);insert into sigov.integracao_outbox(id,tenant_id,tipo_evento,aggregate_id,payload,created_at) values(gen_random_uuid(),@t,'compras.fornecedor.criado',@id,jsonb_build_object('fornecedorId',@id),now())";await c.ExecuteAsync(new CommandDefinition(sql,new{id,t=x.TenantId,codigo,r.TipoPessoa,r.Documento,r.RazaoSocial,r.NomeFantasia,r.Categoria,r.Porte,r.CondicaoPagamento,r.PrazoMedio,r.Observacoes,us=x.UsuarioId.ToString(),corr=x.CorrelationId,key,hash},tx,cancellationToken:ct));await tx.CommitAsync(ct);return id;}
 public async Task AlterarStatusAsync(ComprasContext x,Guid id,AlterarStatusRequest r,CancellationToken ct){var status=r.Status.ToUpperInvariant();if((status is "BLOQUEADO" or "SUSPENSO") && string.IsNullOrWhiteSpace(r.Motivo))throw new ArgumentException("Motivo obrigatório.");await using var c=factory.CreateConnection();await c.OpenAsync(ct);await using var tx=await c.BeginTransactionAsync(ct);var n=await c.ExecuteAsync(new CommandDefinition("update sigov.compras_empresarial_fornecedor set status=@status,version=version+1,updated_at=now(),updated_by=@us,correlation_id=@corr where tenant_id=@t and id=@id and version=@Version and not is_deleted",new{t=x.TenantId,id,status,r.Version,r.Motivo,us=x.UsuarioId.ToString(),corr=x.CorrelationId},tx,cancellationToken:ct));if(n!=1)throw new InvalidOperationException("Fornecedor não encontrado ou versão desatualizada.");await c.ExecuteAsync(new CommandDefinition("insert into sigov.compras_empresarial_historico(tenant_id,aggregate_type,aggregate_id,acao,detalhes,created_by,correlation_id) values(@t,'FORNECEDOR',@id,@status,jsonb_build_object('motivo',@motivo),@us,@corr)",new{t=x.TenantId,id,status,motivo=r.Motivo,us=x.UsuarioId.ToString(),corr=x.CorrelationId},tx,cancellationToken:ct));await tx.CommitAsync(ct);}
 public Task AdicionarContatoAsync(ComprasContext x,Guid id,AdicionarContatoRequest r,string key,CancellationToken ct)=>Child(x,id,key,"CONTATO","insert into sigov.compras_empresarial_fornecedor_contato(id,tenant_id,fornecedor_id,nome,email,telefone,principal,created_by,updated_by,correlation_id) values(@child,@t,@id,@Nome,@Email,@Telefone,@Principal,@us,@us,@corr)",r,ct);
 public Task AdicionarEnderecoAsync(ComprasContext x,Guid id,AdicionarEnderecoRequest r,string key,CancellationToken ct)=>Child(x,id,key,"ENDERECO","insert into sigov.compras_empresarial_fornecedor_endereco(id,tenant_id,fornecedor_id,tipo,logradouro,numero,complemento,bairro,cidade,uf,cep,created_by,updated_by,correlation_id) values(@child,@t,@id,@Tipo,@Logradouro,@Numero,@Complemento,@Bairro,@Cidade,upper(@Uf),@Cep,@us,@us,@corr)",r,ct);
 public Task AdicionarDocumentoAsync(ComprasContext x,Guid id,AdicionarDocumentoRequest r,string key,CancellationToken ct)=>Child(x,id,key,"DOCUMENTO","insert into sigov.compras_empresarial_fornecedor_documento(id,tenant_id,fornecedor_id,documento_ged_id,tipo,obrigatorio,validade,created_by,updated_by,correlation_id) values(@child,@t,@id,@DocumentoGedId,@Tipo,@Obrigatorio,@Validade,@us,@us,@corr)",r,ct);
 private async Task Child(ComprasContext x,Guid id,string key,string op,string sql,object values,CancellationToken ct){await using var c=factory.CreateConnection();await c.OpenAsync(ct);await using var tx=await c.BeginTransactionAsync(ct);await c.ExecuteAsync(new CommandDefinition("select pg_advisory_xact_lock(hashtextextended(@chaveLock,0))",new{chaveLock=$"{x.TenantId:D}|FORNECEDOR|{op}|{key}"},tx,cancellationToken:ct));var hash=HashPayload(new{op,values});var anterior=await c.QuerySingleOrDefaultAsync<IdemComHash>(new CommandDefinition("select recurso_id RecursoId,request_hash RequestHash from sigov.compras_empresarial_idempotencia where tenant_id=@t and operacao=@op and chave=@key",new{t=x.TenantId,op,key},tx,cancellationToken:ct));if(anterior is not null){if(anterior.RequestHash is not null && anterior.RequestHash!=hash)throw new ComprasConcurrencyException("A chave de idempotência já foi usada com conteúdo diferente.");await tx.CommitAsync(ct);return;}var args=new DynamicParameters(values);args.Add("child",Guid.NewGuid());args.Add("t",x.TenantId);args.Add("id",id);args.Add("us",x.UsuarioId.ToString());args.Add("corr",x.CorrelationId);args.Add("key",key);args.Add("op",op);args.Add("hash",hash);var n=await c.ExecuteAsync(new CommandDefinition(sql+";insert into sigov.compras_empresarial_idempotencia(tenant_id,operacao,chave,recurso_id,request_hash) values(@t,@op,@key,@child,@hash) on conflict do nothing;insert into sigov.compras_empresarial_historico(tenant_id,aggregate_type,aggregate_id,acao,created_by,correlation_id) values(@t,'FORNECEDOR',@id,@op,@us,@corr)",args,tx,cancellationToken:ct));if(n!=3)throw new InvalidOperationException("Operação duplicada ou fornecedor inválido.");await tx.CommitAsync(ct);}
 internal static async Task<string> Next(NpgsqlConnection c,NpgsqlTransaction tx,Guid t,string tipo,string prefix,CancellationToken ct){var n=await c.ExecuteScalarAsync<long>(new CommandDefinition("insert into sigov.compras_empresarial_numeracao(tenant_id,tipo,ano,ultimo_numero) values(@t,@tipo,extract(year from current_date)::int,1) on conflict(tenant_id,tipo,ano) do update set ultimo_numero=sigov.compras_empresarial_numeracao.ultimo_numero+1,updated_at=now() returning ultimo_numero",new{t,tipo},tx,cancellationToken:ct));return $"{prefix}-{DateTime.UtcNow:yyyy}-{n:000000}";}internal static string HashPayload(object payload)=>Convert.ToHexString(SHA256.HashData(JsonSerializer.SerializeToUtf8Bytes(payload,new JsonSerializerOptions{PropertyNamingPolicy=JsonNamingPolicy.CamelCase}))).ToLowerInvariant();internal sealed record IdemComHash(Guid RecursoId,string? RequestHash);
}

public sealed class RequisicaoCompraRepository(NpgsqlConnectionFactory factory):IRequisicaoCompraRepository
{
 public async Task<PagedResult<RequisicaoResumo>> ListarAsync(Guid t,RequisicaoFiltro f,CancellationToken ct)
 {
  var p=Math.Max(1,f.Pagina);
  var s=Math.Clamp(f.Tamanho,1,100);
  var status=string.IsNullOrWhiteSpace(f.Status)?null:f.Status.Trim().ToUpperInvariant();
  var busca=string.IsNullOrWhiteSpace(f.Busca)?null:f.Busca.Trim();
  var order=((f.OrdenarPor??"data").Trim().ToLowerInvariant(),(f.Direcao??"desc").Trim().ToLowerInvariant()) switch
  {
   ("numero","asc")=>"r.numero asc, r.id asc",
   ("numero",_)=>"r.numero desc, r.id desc",
   ("status","asc")=>"r.status asc, r.id asc",
   ("status",_)=>"r.status desc, r.id desc",
   ("data","asc")=>"r.created_at asc, r.id asc",
   _=>"r.created_at desc, r.id desc"
  };
  var sql=$@"
select count(*)
from sigov.compras_empresarial_requisicao r
where r.tenant_id=@t and not r.is_deleted
 and (@status is null or r.status=@status)
 and (@busca::text is null or r.numero ilike @term or r.justificativa ilike @term)
 and (@inicio::date is null or r.created_at>=@inicio)
 and (@fim::date is null or r.created_at<(@fim::date+1));
select r.id,r.numero,r.status,r.valor_estimado ValorEstimado,r.data_necessaria DataNecessaria,
 r.created_at DataSolicitacao,
 case when r.ordem_servico_id is not null then 'Ordem de serviço'
      when r.projeto_id is not null then 'Projeto'
      when r.contrato_id is not null then 'Contrato'
      when r.almoxarifado_id is not null then 'Almoxarifado'
      else 'Solicitação direta' end Origem,
 count(i.id)::int Itens,r.version
from sigov.compras_empresarial_requisicao r
left join sigov.compras_empresarial_requisicao_item i
 on i.tenant_id=r.tenant_id and i.requisicao_id=r.id and not i.is_deleted
where r.tenant_id=@t and not r.is_deleted
 and (@status is null or r.status=@status)
 and (@busca::text is null or r.numero ilike @term or r.justificativa ilike @term)
 and (@inicio::date is null or r.created_at>=@inicio)
 and (@fim::date is null or r.created_at<(@fim::date+1))
group by r.id
order by {order}
offset @off limit @s";
  var args=new{t,status,busca,term=$"%{busca}%",inicio=f.DataInicial,fim=f.DataFinal,off=(long)(p-1)*s,s};
  await using var c=factory.CreateConnection();
  using var m=await c.QueryMultipleAsync(new CommandDefinition(sql,args,cancellationToken:ct));
  var total=await m.ReadSingleAsync<long>();
  return new((await m.ReadAsync<RequisicaoResumo>()).AsList(),p,s,total);
 }
 public async Task<RequisicaoDetalhe?> ObterAsync(Guid t,Guid id,CancellationToken ct){const string q=@"select id,numero,status,setor,urgencia,data_necessaria DataNecessaria,justificativa,observacoes,valor_estimado ValorEstimado,version from sigov.compras_empresarial_requisicao where tenant_id=@t and id=@id and not is_deleted;
select id,ordem,tipo,descricao,especificacao,unidade,quantidade,valor_estimado ValorEstimado,permite_parcial PermiteParcial,exige_inspecao ExigeInspecao from sigov.compras_empresarial_requisicao_item where tenant_id=@t and requisicao_id=@id and not is_deleted order by ordem,id;
select acao,detalhes::text Detalhes,created_at CriadoEm from sigov.compras_empresarial_historico where tenant_id=@t and aggregate_type='REQUISICAO' and aggregate_id=@id order by created_at,id";await using var c=factory.CreateConnection();using var m=await c.QueryMultipleAsync(new CommandDefinition(q,new{t,id},cancellationToken:ct));var h=await m.ReadSingleOrDefaultAsync<RequisicaoCabecalho>();if(h is null)return null;var itens=(await m.ReadAsync<RequisicaoItemDetalhe>()).AsList();var historico=(await m.ReadAsync<RequisicaoHistorico>()).AsList();return new(h.Id,h.Numero,h.Status,h.Setor,h.Urgencia,h.DataNecessaria,h.Justificativa,h.Observacoes,h.ValorEstimado,h.Version,itens,historico);}
 public async Task<Guid> CriarAsync(ComprasContext x,CriarRequisicaoRequest r,string key,CancellationToken ct){await using var c=factory.CreateConnection();await c.OpenAsync(ct);await using var tx=await c.BeginTransactionAsync(ct);await c.ExecuteAsync(new CommandDefinition("select pg_advisory_xact_lock(hashtextextended(@chaveLock,0))",new{chaveLock=$"{x.TenantId:D}|REQUISICAO|CRIAR|{key}"},tx,cancellationToken:ct));var hash=FornecedorRepository.HashPayload(r);var anterior=await c.QuerySingleOrDefaultAsync<FornecedorRepository.IdemComHash>(new CommandDefinition("select recurso_id RecursoId,request_hash RequestHash from sigov.compras_empresarial_idempotencia where tenant_id=@t and operacao='REQUISICAO_CRIAR' and chave=@key",new{t=x.TenantId,key},tx,cancellationToken:ct));if(anterior is not null){if(anterior.RequestHash is not null && anterior.RequestHash!=hash)throw new ComprasConcurrencyException("A chave de idempotência já foi usada com conteúdo diferente.");await tx.CommitAsync(ct);return anterior.RecursoId;}var id=Guid.NewGuid();var numero=await FornecedorRepository.Next(c,tx,x.TenantId,"REQUISICAO","RC",ct);var total=Math.Round(r.Itens.Sum(i=>i.Quantidade*i.ValorEstimado),2,MidpointRounding.AwayFromZero);const string head="insert into sigov.compras_empresarial_requisicao(id,tenant_id,numero,solicitante_id,setor,centro_custo_id,projeto_id,contrato_id,ordem_servico_id,almoxarifado_id,urgencia,data_necessaria,justificativa,observacoes,valor_estimado,created_by,updated_by,correlation_id) values(@id,@t,@numero,@usId,@Setor,@CentroCustoId,@ProjetoId,@ContratoId,@OrdemServicoId,@AlmoxarifadoId,upper(@Urgencia),@DataNecessaria,@Justificativa,@Observacoes,@total,@us,@us,@corr)";await c.ExecuteAsync(new CommandDefinition(head,new{id,t=x.TenantId,numero,usId=x.UsuarioId,r.Setor,r.CentroCustoId,r.ProjetoId,r.ContratoId,r.OrdemServicoId,r.AlmoxarifadoId,r.Urgencia,r.DataNecessaria,r.Justificativa,r.Observacoes,total,us=x.UsuarioId.ToString(),corr=x.CorrelationId},tx,cancellationToken:ct));var ordem=0;foreach(var item in r.Itens){ordem++;await c.ExecuteAsync(new CommandDefinition("insert into sigov.compras_empresarial_requisicao_item(tenant_id,requisicao_id,ordem,tipo,descricao,especificacao,unidade,quantidade,valor_estimado,permite_parcial,exige_inspecao,created_by,updated_by,correlation_id) values(@t,@id,@ordem,upper(@Tipo),@Descricao,@Especificacao,@Unidade,@Quantidade,@ValorEstimado,@PermiteParcial,@ExigeInspecao,@us,@us,@corr)",new{t=x.TenantId,id,ordem,item.Tipo,item.Descricao,item.Especificacao,item.Unidade,item.Quantidade,item.ValorEstimado,item.PermiteParcial,item.ExigeInspecao,us=x.UsuarioId.ToString(),corr=x.CorrelationId},tx,cancellationToken:ct));}await c.ExecuteAsync(new CommandDefinition("insert into sigov.compras_empresarial_historico(tenant_id,aggregate_type,aggregate_id,acao,created_by,correlation_id) values(@t,'REQUISICAO',@id,'RASCUNHO_CRIADO',@us,@corr);insert into sigov.compras_empresarial_idempotencia(tenant_id,operacao,chave,recurso_id,request_hash) values(@t,'REQUISICAO_CRIAR',@key,@id,@hash)",new{t=x.TenantId,id,key,hash,us=x.UsuarioId.ToString(),corr=x.CorrelationId},tx,cancellationToken:ct));await tx.CommitAsync(ct);return id;}  public async Task AtualizarAsync(ComprasContext x,Guid id,AtualizarRequisicaoRequest r,CancellationToken ct){await using var c=factory.CreateConnection();await c.OpenAsync(ct);await using var tx=await c.BeginTransactionAsync(ct);var total=Math.Round(r.Itens.Sum(i=>i.Quantidade*i.ValorEstimado),2,MidpointRounding.AwayFromZero);const string update="update sigov.compras_empresarial_requisicao set setor=@Setor,centro_custo_id=@CentroCustoId,projeto_id=@ProjetoId,contrato_id=@ContratoId,ordem_servico_id=@OrdemServicoId,almoxarifado_id=@AlmoxarifadoId,urgencia=upper(@Urgencia),data_necessaria=@DataNecessaria,justificativa=@Justificativa,observacoes=@Observacoes,valor_estimado=@total,status=case when status='DEVOLVIDA' then 'RASCUNHO' else status end,version=version+1,updated_at=now(),updated_by=@us,correlation_id=@corr where tenant_id=@t and id=@id and version=@Version and status in('RASCUNHO','DEVOLVIDA') and not is_deleted";var args=new{t=x.TenantId,id,r.Setor,r.CentroCustoId,r.ProjetoId,r.ContratoId,r.OrdemServicoId,r.AlmoxarifadoId,r.Urgencia,r.DataNecessaria,r.Justificativa,r.Observacoes,total,r.Version,us=x.UsuarioId.ToString(),corr=x.CorrelationId};if(await c.ExecuteAsync(new CommandDefinition(update,args,tx,cancellationToken:ct))!=1)throw new InvalidOperationException("Requisição fora de rascunho/devolvida ou versão desatualizada.");await c.ExecuteAsync(new CommandDefinition("update sigov.compras_empresarial_requisicao_item set is_deleted=true,updated_at=now(),updated_by=@us,correlation_id=@corr where tenant_id=@t and requisicao_id=@id and not is_deleted",args,tx,cancellationToken:ct));var ordem=0;foreach(var item in r.Itens){ordem++;const string upsert="insert into sigov.compras_empresarial_requisicao_item(tenant_id,requisicao_id,ordem,tipo,descricao,especificacao,unidade,quantidade,valor_estimado,permite_parcial,exige_inspecao,created_by,updated_by,correlation_id) values(@t,@id,@ordem,upper(@Tipo),@Descricao,@Especificacao,@Unidade,@Quantidade,@ValorEstimado,@PermiteParcial,@ExigeInspecao,@us,@us,@corr) on conflict(tenant_id,requisicao_id,ordem) do update set tipo=excluded.tipo,descricao=excluded.descricao,especificacao=excluded.especificacao,unidade=excluded.unidade,quantidade=excluded.quantidade,valor_estimado=excluded.valor_estimado,permite_parcial=excluded.permite_parcial,exige_inspecao=excluded.exige_inspecao,is_deleted=false,updated_at=now(),updated_by=excluded.updated_by,correlation_id=excluded.correlation_id,version=sigov.compras_empresarial_requisicao_item.version+1";await c.ExecuteAsync(new CommandDefinition(upsert,new{t=x.TenantId,id,ordem,item.Tipo,item.Descricao,item.Especificacao,item.Unidade,item.Quantidade,item.ValorEstimado,item.PermiteParcial,item.ExigeInspecao,us=x.UsuarioId.ToString(),corr=x.CorrelationId},tx,cancellationToken:ct));}await c.ExecuteAsync(new CommandDefinition("insert into sigov.compras_empresarial_historico(tenant_id,aggregate_type,aggregate_id,acao,detalhes,created_by,correlation_id) values(@t,'REQUISICAO',@id,'RASCUNHO_ATUALIZADO',jsonb_build_object('versao_anterior',@Version),@us,@corr)",args,tx,cancellationToken:ct));await tx.CommitAsync(ct);}
  public async Task<RequisicaoEnvioResultado> EnviarAsync(ComprasContext x,Guid id,long version,string key,CancellationToken ct){await using var c=factory.CreateConnection();await c.OpenAsync(ct);await using var tx=await c.BeginTransactionAsync(ct);try{await c.ExecuteAsync(new CommandDefinition("select pg_advisory_xact_lock(hashtextextended(@chaveLock,0))",new{chaveLock=$"{x.TenantId:D}|REQUISICAO|{id:D}|ENVIO"},tx,cancellationToken:ct));var q=await c.QuerySingleOrDefaultAsync<(string Status,long Version,Guid SolicitanteId)?>(new CommandDefinition("select status,version,solicitante_id SolicitanteId from sigov.compras_empresarial_requisicao where tenant_id=@t and id=@id and not is_deleted for update",new{t=x.TenantId,id},tx,cancellationToken:ct));if(q is null)throw new KeyNotFoundException("Requisição não encontrada no contexto autorizado.");var itens=await c.ExecuteScalarAsync<int>(new CommandDefinition("select count(*) from sigov.compras_empresarial_requisicao_item i where i.tenant_id=@t and i.requisicao_id=@id and not i.is_deleted",new{t=x.TenantId,id},tx,cancellationToken:ct));if(itens==0)throw new InvalidOperationException("Requisição sem itens, fora de rascunho ou versão desatualizada.");var total=await c.ExecuteScalarAsync<decimal>(new CommandDefinition("select coalesce(round(sum(i.quantidade*i.valor_estimado),2),0) from sigov.compras_empresarial_requisicao_item i where i.tenant_id=@t and i.requisicao_id=@id and not i.is_deleted",new{t=x.TenantId,id},tx,cancellationToken:ct));if(total<=0m)throw new InvalidOperationException("Total estimado inválido; revise os itens antes do envio.");var hash=Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes($"{version:D}|{total.ToString("0.00",CultureInfo.InvariantCulture)}|{itens:D}"))).ToLowerInvariant();var anterior=await c.QuerySingleOrDefaultAsync<string>(new CommandDefinition("select request_hash from sigov.compras_empresarial_idempotencia where tenant_id=@t and operacao='REQUISICAO_ENVIAR' and chave=@key",new{t=x.TenantId,key},tx,cancellationToken:ct));if(anterior is not null){if(anterior!=hash)throw new ComprasConcurrencyException("A chave de idempotência já foi usada com conteúdo diferente.");var resultadoOriginal=await c.QuerySingleOrDefaultAsync<string?>(new CommandDefinition("select coalesce(resultado::text,'') from sigov.compras_empresarial_idempotencia where tenant_id=@t and operacao='REQUISICAO_ENVIAR' and chave=@key",new{t=x.TenantId,key},tx,cancellationToken:ct));if(!string.IsNullOrWhiteSpace(resultadoOriginal)){using var doc=System.Text.Json.JsonDocument.Parse(resultadoOriginal);var r=doc.RootElement;await tx.CommitAsync(ct);return new RequisicaoEnvioResultado(System.Guid.Parse(r.GetProperty("id").GetString()!),r.GetProperty("status").GetString()!,r.GetProperty("version").GetInt64(),r.GetProperty("ciclo").GetInt32(),true);}var maxCiclo=await c.ExecuteScalarAsync<int>(new CommandDefinition("select coalesce(max(ciclo),0) from sigov.compras_empresarial_aprovacao where tenant_id=@t and requisicao_id=@id",new{t=x.TenantId,id},tx,cancellationToken:ct));await tx.CommitAsync(ct);return new RequisicaoEnvioResultado(id,q.Value.Status,q.Value.Version,maxCiclo,true);}if(q.Value.Status is not ("RASCUNHO" or "DEVOLVIDA"))throw new InvalidOperationException("Somente requisições em rascunho ou devolvidas podem ser enviadas para aprovação.");if(q.Value.Version!=version)throw new ComprasConcurrencyException("Requisição fora de rascunho/devolvida ou versão desatualizada.");await c.ExecuteAsync(new CommandDefinition("update sigov.compras_empresarial_requisicao set valor_estimado=@total,updated_at=now(),updated_by=@us,correlation_id=@corr where tenant_id=@t and id=@id",new{t=x.TenantId,id,total,us=x.UsuarioId.ToString(),corr=x.CorrelationId},tx,cancellationToken:ct));var nucleo=await AprovacaoRequisicaoRepository.ResolverTenantNucleoAsync(c,tx,x.TenantId,ct);var politica=await c.QuerySingleOrDefaultAsync<(long Id,string Nome)?>(new CommandDefinition("select id,nome from sigov.compras_empresarial_aprovacao_politica where tenant_id=@t and ativo and not is_deleted order by id desc limit 1",new{t=x.TenantId},tx,cancellationToken:ct));var ciclo=await c.ExecuteScalarAsync<int>(new CommandDefinition("select coalesce(max(ciclo),0)+1 from sigov.compras_empresarial_aprovacao where tenant_id=@t and requisicao_id=@id",new{t=x.TenantId,id},tx,cancellationToken:ct));var niveis=new List<(int,decimal)>();if(politica is not null){var niveisBase=await c.QueryAsync<(int,decimal)>(new CommandDefinition("select ordem,limite from sigov.compras_empresarial_aprovacao_politica_nivel where tenant_id=@t and politica_id=@pol and not is_deleted order by ordem",new{t=x.TenantId,pol=politica.Value.Item1},tx,cancellationToken:ct));foreach(var n in niveisBase)niveis.Add(n);}var alcadaInsuficiente=politica is not null&&niveis.Count>0&&total>niveis.Max(n=>n.Item2);var etapas=new List<(int,decimal)>();var semAprovadorNiveis=new List<int>();foreach(var n in niveis){etapas.Add(n);if(n.Item2>=total)break;}var bloqueadas=new List<int>();const string insereEtapa="insert into sigov.compras_empresarial_aprovacao(id,tenant_id,requisicao_id,nivel,aprovador_id,limite,status,causa_bloqueio,regra_snapshot,ciclo,created_by,updated_by,correlation_id) values(gen_random_uuid(),@t,@rq,@nivel,@aprovador,@limite,'PENDENTE',@causa,jsonb_build_object('total_requisicao',@total,'alcada_etapa',@limite,'etapa',@nivel,'ciclo',@ciclo,'versao_requisicao',@versaoReq,'politica_id',@polId,'politica_nome',@polNome,'solicitante_id',@solicitanteId,'itens',(select coalesce(jsonb_agg(jsonb_build_object('id',i.id,'ordem',i.ordem,'tipo',i.tipo,'descricao',i.descricao,'especificacao',i.especificacao,'unidade',i.unidade,'quantidade',i.quantidade,'valor_estimado',i.valor_estimado,'permite_parcial',i.permite_parcial,'exige_inspecao',i.exige_inspecao) order by i.ordem),'[]'::jsonb) from sigov.compras_empresarial_requisicao_item i where i.tenant_id=@t and i.requisicao_id=@rq and not i.is_deleted)),@ciclo,@us,@us,@corr)";if(etapas.Count==0){await c.ExecuteAsync(new CommandDefinition(insereEtapa,new{t=x.TenantId,rq=id,nivel=1,aprovador=(Guid?)null,limite=0m,ciclo,versaoReq=version,solicitanteId=q.Value.SolicitanteId,polId=(long?)null,polNome=(string?)null,total,causa="SEM_POLITICA",us=x.UsuarioId.ToString(),corr=x.CorrelationId},tx,cancellationToken:ct));}else{foreach(var e in etapas){var elegiveis=(await AprovacaoRequisicaoRepository.AprovadoresElegiveisAsync(c,tx,nucleo,e.Item2,ct)).Where(ap=>ap!=x.UsuarioId&&ap!=q.Value.SolicitanteId).ToList();var topoAlcada=alcadaInsuficiente&&e.Item1==etapas[^1].Item1;if(elegiveis.Count==0||topoAlcada){bloqueadas.Add(e.Item1);if(!topoAlcada)semAprovadorNiveis.Add(e.Item1);await c.ExecuteAsync(new CommandDefinition(insereEtapa,new{t=x.TenantId,rq=id,nivel=e.Item1,aprovador=(Guid?)null,limite=e.Item2,ciclo,versaoReq=version,solicitanteId=q.Value.SolicitanteId,polId=politica?.Item1,polNome=politica?.Item2,total,causa=topoAlcada?"ALCADA_INSUFICIENTE":"SEM_APROVADOR",us=x.UsuarioId.ToString(),corr=x.CorrelationId},tx,cancellationToken:ct));}else{foreach(var aprovador in elegiveis){await c.ExecuteAsync(new CommandDefinition(insereEtapa,new{t=x.TenantId,rq=id,nivel=e.Item1,aprovador=(Guid)aprovador,limite=e.Item2,ciclo,versaoReq=version,solicitanteId=q.Value.SolicitanteId,polId=politica?.Item1,polNome=politica?.Item2,total,causa=(string?)null,us=x.UsuarioId.ToString(),corr=x.CorrelationId},tx,cancellationToken:ct));}}}}if(etapas.Count==0){await AprovacaoRequisicaoRepository.RegistrarPendenciaAsync(c,tx,x.TenantId,id,"APROVACAO_SEM_POLITICA","Política de aprovação ausente","Configure a política de aprovação por alçada neste contexto institucional para liberar as etapas de decisão.",ct);}if(semAprovadorNiveis.Count>0){await AprovacaoRequisicaoRepository.RegistrarPendenciaAsync(c,tx,x.TenantId,id,"APROVACAO_SEM_APROVADOR","Aprovação sem aprovador habilitado","Etapas sem aprovador habilitado: "+string.Join(", ",semAprovadorNiveis.Select(b=>b.ToString(CultureInfo.InvariantCulture)))+". Ajuste permissões ou alçadas dos perfis de acesso (solicitante segregado).",ct);}if(alcadaInsuficiente){await AprovacaoRequisicaoRepository.RegistrarPendenciaAsync(c,tx,x.TenantId,id,"APROVACAO_ALCADA_INSUFICIENTE","Aprovação com alçada insuficiente",$"O total estimado ({total.ToString("0.00",CultureInfo.InvariantCulture)}) excede o maior limite da política ativa ({niveis.Max(n=>n.Item2).ToString("0.00",CultureInfo.InvariantCulture)}); amplie os limites de alçada ou revise a requisição para liberar a etapa final.",ct);}await c.ExecuteAsync(new CommandDefinition("update sigov.compras_empresarial_requisicao set status='PENDENTE_APROVACAO',valor_estimado=@total,version=version+1,updated_at=now(),updated_by=@us,correlation_id=@corr where tenant_id=@t and id=@id",new{t=x.TenantId,id,total,us=x.UsuarioId.ToString(),corr=x.CorrelationId},tx,cancellationToken:ct));await c.ExecuteAsync(new CommandDefinition("insert into sigov.compras_empresarial_historico(tenant_id,aggregate_type,aggregate_id,acao,detalhes,created_by,correlation_id) values(@t,'REQUISICAO',@id,'ENVIADA_PARA_APROVACAO',jsonb_build_object('ciclo',@ciclo,'total',@total,'etapas',@etapasCount,'alcada_insuficiente',@alcadaInsuficiente),@us,@corr)",new{t=x.TenantId,id,ciclo,total,etapasCount=etapas.Count==0?1:etapas.Count,alcadaInsuficiente,us=x.UsuarioId.ToString(),corr=x.CorrelationId},tx,cancellationToken:ct));await c.ExecuteAsync(new CommandDefinition("insert into sigov.compras_empresarial_idempotencia(tenant_id,operacao,chave,recurso_id,request_hash) values(@t,'REQUISICAO_ENVIAR',@key,@id,@hash)",new{t=x.TenantId,key,id,hash},tx,cancellationToken:ct));await c.ExecuteAsync(new CommandDefinition("update sigov.compras_empresarial_idempotencia set resultado=jsonb_build_object('id',@id::text,'status','PENDENTE_APROVACAO','version',@v2,'ciclo',@ciclo) where tenant_id=@t and operacao='REQUISICAO_ENVIAR' and chave=@key",new{t=x.TenantId,key,id,v2=version+1,ciclo},tx,cancellationToken:ct));await tx.CommitAsync(ct);return new RequisicaoEnvioResultado(id,"PENDENTE_APROVACAO",version+1,ciclo,false);}catch{try{await tx.RollbackAsync(ct);}catch(InvalidOperationException){}throw;}}
