public sealed class ComprasDashboardRepository(NpgsqlConnectionFactory factory):IComprasDashboardRepository
{public async Task<ComprasDashboard> ObterAsync(Guid t,CancellationToken ct){const string q="select coalesce(sum(valor_estimado),0) TotalSolicitado,coalesce(sum(valor_estimado) filter(where status in('APROVADA','EM_COTACAO','PEDIDA','RECEBIDA','ENCERRADA')),0) ValorAprovado,(select count(*) from sigov.compras_empresarial_aprovacao where tenant_id=@t and status='PENDENTE')::int AprovacoesPendentes,(select count(*) from sigov.compras_empresarial_cotacao where tenant_id=@t and status in('ABERTA','EM_RESPOSTA'))::int CotacoesAbertas,(select count(*) from sigov.compras_empresarial_pedido where tenant_id=@t and previsao<current_date and status not in('RECEBIDO','ENCERRADO','CANCELADO'))::int PedidosAtrasados,(select count(*) from sigov.compras_empresarial_pedido where tenant_id=@t and status in('CONFIRMADO','PARCIALMENTE_RECEBIDO'))::int RecebimentosPendentes,(select count(*) from sigov.compras_empresarial_fatura where tenant_id=@t and status='BLOQUEADA')::int FaturasBloqueadas,(select count(*) from sigov.compras_empresarial_fornecedor_documento where tenant_id=@t and validade between current_date and current_date+30 and not is_deleted)::int DocumentosVencendo from sigov.compras_empresarial_requisicao where tenant_id=@t and not is_deleted";await using var c=factory.CreateConnection();return await c.QuerySingleAsync<ComprasDashboard>(new CommandDefinition(q,new{t},cancellationToken:ct));}}

public sealed class RecebimentoCompraRepository(NpgsqlConnectionFactory factory):IRecebimentoCompraRepository
{
 public async Task<CentralRecebimentos> ListarAsync(Guid t,RecebimentoFiltro f,CancellationToken ct)
 {
  var page=Math.Max(1,f.Pagina);var size=Math.Clamp(f.Tamanho,1,100);
  const string where=@"r.tenant_id=@t and (@fornecedor is null or fo.razao_social ilike @termFornecedor::text or fo.nome_fantasia ilike @termFornecedor::text) and (@pedido is null or p.numero ilike @termPedido::text) and (@status is null or r.status=@status::text) and (@almox is null or r.almoxarifado_id=@almox::uuid) and (@responsavel is null or r.created_by ilike @termResponsavel::text) and (@inicio::timestamptz is null or r.data_operacao>=@inicio::timestamptz) and (@fim::date is null or r.data_operacao<(@fim::date+1))";
  var sql=$@"select count(*) from sigov.compras_empresarial_recebimento r join sigov.compras_empresarial_pedido p on p.id=r.pedido_id and p.tenant_id=r.tenant_id join sigov.compras_empresarial_fornecedor fo on fo.id=p.fornecedor_id and fo.tenant_id=p.tenant_id where {where};
select r.id,r.pedido_id PedidoId,p.numero PedidoNumero,coalesce(fo.nome_fantasia,fo.razao_social) FornecedorNome,r.status,r.documento,a.nome AlmoxarifadoNome,r.created_at CriadoEm,r.created_by Responsavel,count(ri.id) filter(where ri.quantidade_rejeitada>0)::int Divergencias from sigov.compras_empresarial_recebimento r join sigov.compras_empresarial_pedido p on p.id=r.pedido_id and p.tenant_id=r.tenant_id join sigov.compras_empresarial_fornecedor fo on fo.id=p.fornecedor_id and fo.tenant_id=p.tenant_id join sigov.estoque_almoxarifado a on a.id=r.almoxarifado_id and a.tenant_id=r.tenant_id left join sigov.compras_empresarial_recebimento_item ri on ri.recebimento_id=r.id and ri.tenant_id=r.tenant_id where {where} group by r.id,p.id,fo.id,a.id order by r.created_at desc,r.id desc offset @off limit @size;
select (select count(*) from sigov.compras_empresarial_pedido p where p.tenant_id=@t and p.status in('CONFIRMADO','PARCIALMENTE_RECEBIDO') and not p.is_deleted) Aptos,count(*) filter(where r.status='EM_CONFERENCIA') EmConferencia,count(*) filter(where r.status='CONCLUIDO') Concluidos,count(*) filter(where exists(select 1 from sigov.compras_empresarial_recebimento_item x where x.tenant_id=r.tenant_id and x.recebimento_id=r.id and x.quantidade_rejeitada>0)) Divergencias from sigov.compras_empresarial_recebimento r join sigov.compras_empresarial_pedido p on p.id=r.pedido_id and p.tenant_id=r.tenant_id join sigov.compras_empresarial_fornecedor fo on fo.id=p.fornecedor_id and fo.tenant_id=p.tenant_id where {where}";
  var args=new{t,fornecedor=Clean(f.Fornecedor),termFornecedor=$"%{Clean(f.Fornecedor)}%",pedido=Clean(f.Pedido),termPedido=$"%{Clean(f.Pedido)}%",status=Clean(f.Status)?.ToUpperInvariant(),almox=f.AlmoxarifadoId,responsavel=Clean(f.Responsavel),termResponsavel=$"%{Clean(f.Responsavel)}%",inicio=f.DataInicial,fim=f.DataFinal,off=(page-1)*size,size};
  await using var c=factory.CreateConnection();using var m=await c.QueryMultipleAsync(new CommandDefinition(sql,args,cancellationToken:ct));var total=await m.ReadSingleAsync<long>();var items=(await m.ReadAsync<RecebimentoResumo>()).AsList();var totals=await m.ReadSingleAsync<RecebimentoTotais>();return new(new(items,page,size,total),totals);
 }
 public async Task<PedidoParaRecebimento?> ObterPedidoAsync(Guid t,Guid id,CancellationToken ct)
 {
  const string sql=@"select p.id,p.numero,p.status,p.fornecedor_id FornecedorId,coalesce(f.nome_fantasia,f.razao_social) Fornecedor,p.version from sigov.compras_empresarial_pedido p join sigov.compras_empresarial_fornecedor f on f.id=p.fornecedor_id and f.tenant_id=p.tenant_id where p.tenant_id=@t and p.id=@id and not p.is_deleted;
select i.id,i.produto_id ProdutoId,pr.nome Produto,pr.unidade,i.quantidade QuantidadePedida,i.quantidade_cancelada QuantidadeCancelada,coalesce(sum(ri.quantidade_fisica) filter (where ri.divergencia_origem_id is null),0) QuantidadeFisica,coalesce(sum(ri.quantidade_aceita),0) QuantidadeAceita,coalesce(sum(ri.quantidade_rejeitada),0) QuantidadeRejeitada,coalesce(sum(ri.quantidade_conferencia),0) QuantidadeEmConferencia,(i.quantidade-i.quantidade_cancelada-coalesce(sum(ri.quantidade_fisica) filter (where ri.divergencia_origem_id is null),0)) QuantidadePendente,i.exige_inspecao ExigeInspecao from sigov.compras_empresarial_pedido_item i join sigov.estoque_produto pr on pr.id=i.produto_id and pr.tenant_id=i.tenant_id left join sigov.compras_empresarial_recebimento_item ri on ri.pedido_item_id=i.id and ri.tenant_id=i.tenant_id where i.tenant_id=@t and i.pedido_id=@id group by i.id,pr.id order by i.id;
select id,nome from sigov.estoque_almoxarifado where tenant_id=@t and ativo order by nome,id";
  await using var c=factory.CreateConnection();using var m=await c.QueryMultipleAsync(new CommandDefinition(sql,new{t,id},cancellationToken:ct));var h=await m.ReadSingleOrDefaultAsync<PedidoHeader>();if(h is null)return null;var items=(await m.ReadAsync<PedidoRecebimentoItem>()).AsList();return new(h.Id,h.Numero,h.Status,h.FornecedorId,h.Fornecedor,h.Version,items,(await m.ReadAsync<AlmoxarifadoOpcao>()).AsList());
 }
 public async Task<RecebimentoDetalhe?> ObterAsync(Guid t,Guid id,CancellationToken ct)
 {
  const string sql=@"select r.id,r.pedido_id PedidoId,p.numero PedidoNumero,coalesce(f.nome_fantasia,f.razao_social) Fornecedor,r.documento,a.nome Almoxarifado,r.data_operacao DataOperacao,r.status,r.resultado_inspecao ResultadoInspecao,r.observacoes,r.version
from sigov.compras_empresarial_recebimento r join sigov.compras_empresarial_pedido p on p.id=r.pedido_id and p.tenant_id=r.tenant_id join sigov.compras_empresarial_fornecedor f on f.id=p.fornecedor_id and f.tenant_id=p.tenant_id join sigov.estoque_almoxarifado a on a.id=r.almoxarifado_id and a.tenant_id=r.tenant_id where r.tenant_id=@t and r.id=@id;
select ri.id,pr.nome Produto,pr.unidade,ri.quantidade_fisica QuantidadeFisica,ri.quantidade_aceita QuantidadeAceita,ri.quantidade_rejeitada QuantidadeRejeitada,ri.quantidade_conferencia QuantidadeConferencia,ri.lote,ri.validade,ri.numero_serie NumeroSerie,ri.divergencia_origem_id DivergenciaOrigemId from sigov.compras_empresarial_recebimento_item ri join sigov.estoque_produto pr on pr.id=ri.produto_id and pr.tenant_id=ri.tenant_id where ri.tenant_id=@t and ri.recebimento_id=@id order by ri.id;
select tipo,detalhes::text Detalhes,ocorrido_em OcorridoEm from sigov.compras_empresarial_recebimento_evento where tenant_id=@t and recebimento_id=@id order by ocorrido_em,id";
  await using var c=factory.CreateConnection();using var m=await c.QueryMultipleAsync(new CommandDefinition(sql,new{t,id},cancellationToken:ct));var h=await m.ReadSingleOrDefaultAsync<RecebimentoHeader>();if(h is null)return null;return new(h.Id,h.PedidoId,h.PedidoNumero,h.Fornecedor,h.Documento,h.Almoxarifado,h.DataOperacao.ToUniversalTime(),h.Status,h.ResultadoInspecao,h.Observacoes,h.Version,(await m.ReadAsync<RecebimentoItemDetalhe>()).AsList(),(await m.ReadAsync<RecebimentoEvento>()).AsList());
 }
 public async Task<RecebimentoCriado> CriarEConfirmarAsync(ComprasContext x,CriarRecebimentoRequest r,string key,CancellationToken ct)
 {
  await using var c=factory.CreateConnection();await c.OpenAsync(ct);await using var tx=await c.BeginTransactionAsync(ct);
  const string idempotencyQuery="select id,status from sigov.compras_empresarial_recebimento where tenant_id=@t and idempotency_key=@key";
  var idempotencyArgs=new{t=x.TenantId,key};
  var old=await c.QuerySingleOrDefaultAsync<RecebimentoExistente>(new CommandDefinition(idempotencyQuery,idempotencyArgs,tx,cancellationToken:ct));if(old is not null){await tx.CommitAsync(ct);return new(old.Id,old.Status,true);}
  var pedido=await c.QuerySingleOrDefaultAsync<PedidoLock>(new CommandDefinition("select id,status,version from sigov.compras_empresarial_pedido where tenant_id=@t and id=@id and not is_deleted for update",new{t=x.TenantId,id=r.PedidoId},tx,cancellationToken:ct));
  // A second request can observe no receipt before waiting for the order lock. Under
  // READ COMMITTED, query again after the lock so that a retry committed by the first
  // request is returned instead of being rejected as a stale order version.
  old=await c.QuerySingleOrDefaultAsync<RecebimentoExistente>(new CommandDefinition(idempotencyQuery,idempotencyArgs,tx,cancellationToken:ct));if(old is not null){await tx.CommitAsync(ct);return new(old.Id,old.Status,true);}
   if(pedido is null||pedido.Version!=r.PedidoVersion||pedido.Status is not ("CONFIRMADO" or "PARCIALMENTE_RECEBIDO" or "RECEBIDO"))throw new InvalidOperationException("Pedido inexistente, alterado ou em situação incompatível com recebimento.");
    if(pedido.Status == "RECEBIDO" && r.Itens.Any(i => !i.DivergenciaOrigemId.HasValue))throw new InvalidOperationException("O pedido já se encontra na situação RECEBIDO; novas entregas originais não são permitidas, apenas reposições autorizadas.");
    if(!await c.ExecuteScalarAsync<bool>(new CommandDefinition("select exists(select 1 from sigov.estoque_almoxarifado where tenant_id=@t and id=@id and ativo)",new{t=x.TenantId,id=r.AlmoxarifadoId},tx,cancellationToken:ct)))throw new InvalidOperationException("O almoxarifado de destino não pertence ao contexto autorizado ou está inativo.");

    if(r.Itens.Count == 0 || r.Itens.Any(i => i.Quantidade <= 0m))throw new InvalidOperationException("As quantidades informadas para recebimento devem ser estritamente positivas.");

    var ids=r.Itens.Select(i=>i.PedidoItemId).Distinct().ToArray();
    var db=(await c.QueryAsync<ItemLock>(new CommandDefinition(@"select i.id,i.produto_id ProdutoId,i.quantidade-i.quantidade_cancelada-coalesce((select sum(ri.quantidade_fisica) from sigov.compras_empresarial_recebimento_item ri where ri.tenant_id=i.tenant_id and ri.pedido_item_id=i.id),0) SaldoTotal,i.quantidade-i.quantidade_cancelada-coalesce((select sum(ri.quantidade_fisica) from sigov.compras_empresarial_recebimento_item ri where ri.tenant_id=i.tenant_id and ri.pedido_item_id=i.id and ri.divergencia_origem_id is null),0) Pendente,i.exige_inspecao ExigeInspecao from sigov.compras_empresarial_pedido_item i where i.tenant_id=@t and i.pedido_id=@pedido and i.id=any(@ids) for update",new{t=x.TenantId,pedido=r.PedidoId,ids},tx,cancellationToken:ct))).ToDictionary(i=>i.Id);
    if(db.Count!=ids.Length)throw new InvalidOperationException("Um item não pertence ao pedido ou a quantidade supera o saldo permitido.");
    var originaisAgrupados=r.Itens.Where(i=>!i.DivergenciaOrigemId.HasValue).GroupBy(i=>i.PedidoItemId).ToDictionary(g=>g.Key,g=>g.Sum(x=>x.Quantidade));
    foreach(var (pid,totalQtd) in originaisAgrupados){if(!db.TryGetValue(pid,out var it)||totalQtd<=0||totalQtd>it.Pendente)throw new InvalidOperationException("Um item não pertence ao pedido ou a quantidade supera o saldo permitido.");}

    var divIds=r.Itens.Where(i=>i.DivergenciaOrigemId.HasValue).Select(i=>i.DivergenciaOrigemId!.Value).Distinct().ToArray();
    var divergenciasValidadas=new Dictionary<long,DivergenciaReposicaoLock>();
    foreach(var divId in divIds)
    {
     var div=await c.QuerySingleOrDefaultAsync<DivergenciaReposicaoLock>(new CommandDefinition(@"select d.id,d.recebimento_id RecebimentoId,d.recebimento_item_id RecebimentoItemId,d.reposicao_autorizada ReposicaoAutorizada,coalesce(d.quantidade_reposicao,0) QuantidadeReposicao,coalesce(d.reposicao_recebida,0) ReposicaoRecebida,d.situacao Situacao,ri.pedido_item_id PedidoItemId,ri.produto_id ProdutoId,r.pedido_id PedidoId from sigov.compras_empresarial_recebimento_divergencia d join sigov.compras_empresarial_recebimento_item ri on ri.id=d.recebimento_item_id and ri.tenant_id=d.tenant_id join sigov.compras_empresarial_recebimento r on r.id=d.recebimento_id and r.tenant_id=d.tenant_id where d.tenant_id=@t and d.id=@divId for update",new{t=x.TenantId,divId},tx,cancellationToken:ct));
     if(div is null)throw new InvalidOperationException("A divergência informada para reposição não existe no contexto autorizado.");
     if(div.PedidoId!=r.PedidoId)throw new InvalidOperationException("A divergência informada não corresponde ao pedido especificado.");
     if(div.Situacao=="ENCERRADA")throw new InvalidOperationException("A divergência de origem já foi encerrada e não permite novos recebimentos de reposição.");
     if(!div.ReposicaoAutorizada)throw new InvalidOperationException("A reposição ainda não foi autorizada para a divergência informada.");
     divergenciasValidadas[divId]=div;
    }

    foreach(var item in r.Itens.Where(i=>i.DivergenciaOrigemId.HasValue))
    {
     var div=divergenciasValidadas[item.DivergenciaOrigemId!.Value];
     if(item.PedidoItemId!=div.PedidoItemId)throw new InvalidOperationException("O item do pedido informado não corresponde ao item original da divergência; não é permitido consumir autorização de reposição para outro item.");
     var lockedItem=db[item.PedidoItemId];
     if(lockedItem.ProdutoId!=div.ProdutoId)throw new InvalidOperationException("O produto do item informado diverge do produto registrado na divergência de origem.");
    }

    var reposicoesAgrupadas=r.Itens.Where(i=>i.DivergenciaOrigemId.HasValue).GroupBy(i=>i.DivergenciaOrigemId!.Value).ToDictionary(g=>g.Key,g=>g.Sum(x=>x.Quantidade));
    foreach(var (divId,totalQtd) in reposicoesAgrupadas)
    {
     var div=divergenciasValidadas[divId];
     var saldoRep=div.QuantidadeReposicao-div.ReposicaoRecebida;
     if(totalQtd<=0||totalQtd>saldoRep)throw new InvalidOperationException($"A quantidade agregada a receber na reposição ({totalQtd:0.####}) supera o saldo autorizado ({saldoRep:0.####}).");
    }

    var id=Guid.NewGuid();
    var inspecao=r.Itens.Any(i=>db[i.PedidoItemId].ExigeInspecao);
    var status=inspecao?"EM_CONFERENCIA":"CONCLUIDO";
    var user=x.UsuarioId.ToString();

    foreach(var (divId,totalQtd) in reposicoesAgrupadas)
    {
     await c.ExecuteAsync(new CommandDefinition(@"update sigov.compras_empresarial_recebimento_divergencia set reposicao_recebida=coalesce(reposicao_recebida,0)+@q,version=version+1,updated_at=now(),updated_by=@user,correlation_id=@corr where tenant_id=@t and id=@divId",new{t=x.TenantId,divId,q=totalQtd,user,corr=x.CorrelationId},tx,cancellationToken:ct));
     await c.ExecuteAsync(new CommandDefinition(@"insert into sigov.compras_empresarial_recebimento_divergencia_evento(tenant_id,divergencia_id,tipo,detalhes,usuario_id,correlation_id) values(@t,@divId,'REPOSICAO_RECEBIDA',jsonb_build_object('quantidade_recebida',@q,'recebimento_id',@id::text),@usuario,@corr)",new{t=x.TenantId,divId,q=totalQtd,id,usuario=x.UsuarioId,corr=x.CorrelationId},tx,cancellationToken:ct));
    }

    await c.ExecuteAsync(new CommandDefinition(@"insert into sigov.compras_empresarial_recebimento(id,tenant_id,pedido_id,documento,idempotency_key,resultado_inspecao,status,almoxarifado_id,data_operacao,observacoes,confirmado_em,created_by,updated_by,correlation_id) values(@id,@t,@pedido,@documento,@key,@resultado,@status,@almox,@data,@observacoes,now(),@user,@user,@corr)",new{id,t=x.TenantId,pedido=r.PedidoId,documento=r.Documento,key,resultado=inspecao?"PENDENTE":"APROVADO",status,almox=r.AlmoxarifadoId,data=r.DataOperacao,observacoes=r.Observacoes,user,corr=x.CorrelationId},tx,cancellationToken:ct));
    foreach(var item in r.Itens){var locked=db[item.PedidoItemId];var aceita=locked.ExigeInspecao?0:item.Quantidade;var conferencia=locked.ExigeInspecao?item.Quantidade:0;await c.ExecuteAsync(new CommandDefinition(@"insert into sigov.compras_empresarial_recebimento_item(tenant_id,recebimento_id,pedido_item_id,produto_id,quantidade_fisica,quantidade_aceita,quantidade_conferencia,lote,validade,numero_serie,divergencia_origem_id) values(@t,@id,@item,@produto,@q,@aceita,@conferencia,@lote,@validade,@serie,@divOrigem)",new{t=x.TenantId,id,item=item.PedidoItemId,produto=locked.ProdutoId,q=item.Quantidade,aceita,conferencia,item.Lote,item.Validade,serie=item.NumeroSerie,divOrigem=item.DivergenciaOrigemId},tx,cancellationToken:ct));if(aceita>0){await c.ExecuteAsync(new CommandDefinition("insert into sigov.estoque_saldo(tenant_id,produto_id,almoxarifado_id,quantidade) values(@t,@produto,@almox,@q) on conflict(tenant_id,produto_id,almoxarifado_id) do update set quantidade=sigov.estoque_saldo.quantidade+excluded.quantidade,updated_at=now();insert into sigov.estoque_movimento(tenant_id,produto_id,almoxarifado_id,tipo,quantidade,origem,origem_id) values(@t,@produto,@almox,'ENTRADA',@q,'RECEBIMENTO_COMPRA',@id)",new{t=x.TenantId,produto=locked.ProdutoId,almox=r.AlmoxarifadoId,q=aceita,id},tx,cancellationToken:ct));}}
    var pendente=await c.ExecuteScalarAsync<bool>(new CommandDefinition("select exists(select 1 from sigov.compras_empresarial_pedido_item i where i.tenant_id=@t and i.pedido_id=@pedido and i.quantidade-i.quantidade_cancelada-coalesce((select sum(ri.quantidade_fisica) from sigov.compras_empresarial_recebimento_item ri where ri.tenant_id=i.tenant_id and ri.pedido_item_id=i.id and ri.divergencia_origem_id is null),0)>0)",new{t=x.TenantId,pedido=r.PedidoId},tx,cancellationToken:ct));
   var pedidoStatus=(pedido.Status=="RECEBIDO"||!pendente)?"RECEBIDO":"PARCIALMENTE_RECEBIDO";
   await c.ExecuteAsync(new CommandDefinition("update sigov.compras_empresarial_pedido set status=@pedidoStatus,version=version+1,updated_at=now(),updated_by=@user,correlation_id=@corr where tenant_id=@t and id=@pedido and version=@version;insert into sigov.compras_empresarial_recebimento_evento(tenant_id,recebimento_id,tipo,detalhes,usuario_id,correlation_id) values(@t,@id,'CONFIRMADO',jsonb_build_object('pedido_id',@pedido,'status',@status),@usuario,@corr)",new{t=x.TenantId,pedido=r.PedidoId,pedidoStatus,version=r.PedidoVersion,user,usuario=x.UsuarioId,id,status,corr=x.CorrelationId},tx,cancellationToken:ct));
  if(inspecao&&await c.ExecuteAsync(new CommandDefinition(@"insert into sigov.pendencia_operacional(tenant_id,modulo,recurso,tipo,entidade,entidade_id,gravidade,titulo,descricao,rota_acao,status)
select m.core_tenant_id,'COMPRAS_EMPRESARIAIS','RECEBIMENTO','CONFERENCIA_RECEBIMENTO','compras_empresarial_recebimento',@id::text,'ALTA','Conferir recebimento '||@documento,'Itens recebidos aguardam inspeção antes da entrada no estoque.','/ComprasEmpresariais/Recebimentos/'||@id::text,'ABERTA' from sigov.enterprise_tenant_mapping m where m.enterprise_tenant_id=@t and m.ativo
on conflict(tenant_id,modulo,tipo,entidade,entidade_id) where status in('ABERTA','EM_TRATAMENTO') do update set titulo=excluded.titulo,descricao=excluded.descricao,rota_acao=excluded.rota_acao",new{t=x.TenantId,id,documento=r.Documento},tx,cancellationToken:ct))!=1)throw new InvalidOperationException("O tenant empresarial não possui vínculo ativo com o contexto institucional; a pendência de conferência não pôde ser criada.");
  var persisted=await c.QuerySingleAsync<RecebimentoExistente>(new CommandDefinition("select id,status from sigov.compras_empresarial_recebimento where tenant_id=@t and id=@id",new{t=x.TenantId,id},tx,cancellationToken:ct));await tx.CommitAsync(ct);return new(persisted.Id,persisted.Status,false);
 }
 public async Task<RecebimentoCriado> ConcluirInspecaoAsync(ComprasContext x,Guid id,ConcluirInspecaoRequest r,CancellationToken ct)
 {
  await using var c=factory.CreateConnection();await c.OpenAsync(ct);await using var tx=await c.BeginTransactionAsync(ct);
  var commandHash=InspectionHash(r);
  var receipt=await c.QuerySingleOrDefaultAsync<RecebimentoInspecaoLock>(new CommandDefinition("select id,status,version,almoxarifado_id AlmoxarifadoId,inspecao_hash InspecaoHash from sigov.compras_empresarial_recebimento where tenant_id=@t and id=@id for update",new{t=x.TenantId,id},tx,cancellationToken:ct));
  if(receipt is null)throw new InvalidOperationException("Recebimento não encontrado no contexto autorizado.");
  if(receipt.Status is "CONCLUIDO" or "COM_DIVERGENCIA")
  {
   if(receipt.InspecaoHash is null)throw new InvalidOperationException("O recebimento já foi encerrado, mas o registro legado não permite comprovar que este comando é uma repetição.");
   if(!CryptographicOperations.FixedTimeEquals(Convert.FromHexString(receipt.InspecaoHash),Convert.FromHexString(commandHash)))throw new InvalidOperationException("O recebimento já foi encerrado com uma decisão diferente. Consulte o estado persistido antes de prosseguir.");
   await tx.CommitAsync(ct);return new(id,receipt.Status,true);
  }
  if(receipt.Status!="EM_CONFERENCIA"||receipt.Version!=r.Version)throw new InvalidOperationException("O recebimento foi alterado ou não está mais aguardando conferência. Recarregue os dados.");
  var pending=(await c.QueryAsync<InspecaoItemLock>(new CommandDefinition("select id,produto_id ProdutoId,quantidade_conferencia QuantidadeConferencia from sigov.compras_empresarial_recebimento_item where tenant_id=@t and recebimento_id=@id and quantidade_conferencia>0 order by id for update",new{t=x.TenantId,id},tx,cancellationToken:ct))).AsList();
  var items=pending.ToDictionary(i=>i.Id);
  if(items.Count!=r.Itens.Count||r.Itens.Any(i=>!items.TryGetValue(i.RecebimentoItemId,out var db)||i.QuantidadeAceita+i.QuantidadeRejeitada!=db.QuantidadeConferencia))throw new InvalidOperationException("A decisão deve incluir uma única classificação integral para todos os itens ainda em conferência, sem alterar o total físico.");
  var mappingCount=await c.ExecuteScalarAsync<int>(new CommandDefinition("select count(*) from sigov.enterprise_tenant_mapping where enterprise_tenant_id=@t and ativo",new{t=x.TenantId},tx,cancellationToken:ct));
  if(mappingCount!=1)throw new InvalidOperationException("O tenant empresarial não possui um único vínculo institucional ativo; a conclusão foi cancelada com segurança.");
  foreach(var decision in r.Itens){var item=items[decision.RecebimentoItemId];await c.ExecuteAsync(new CommandDefinition("update sigov.compras_empresarial_recebimento_item set quantidade_aceita=@aceita,quantidade_rejeitada=@rejeitada,quantidade_conferencia=0 where tenant_id=@t and recebimento_id=@id and id=@item",new{t=x.TenantId,id,item=decision.RecebimentoItemId,aceita=decision.QuantidadeAceita,rejeitada=decision.QuantidadeRejeitada},tx,cancellationToken:ct));if(decision.QuantidadeAceita>0)await c.ExecuteAsync(new CommandDefinition("insert into sigov.estoque_saldo(tenant_id,produto_id,almoxarifado_id,quantidade) values(@t,@produto,@almox,@q) on conflict(tenant_id,produto_id,almoxarifado_id) do update set quantidade=sigov.estoque_saldo.quantidade+excluded.quantidade,updated_at=now();insert into sigov.estoque_movimento(tenant_id,produto_id,almoxarifado_id,tipo,quantidade,origem,origem_id) values(@t,@produto,@almox,'ENTRADA',@q,'INSPECAO_RECEBIMENTO_COMPRA',@id)",new{t=x.TenantId,produto=item.ProdutoId,almox=receipt.AlmoxarifadoId,q=decision.QuantidadeAceita,id},tx,cancellationToken:ct));}
  if(await c.ExecuteScalarAsync<bool>(new CommandDefinition("select exists(select 1 from sigov.compras_empresarial_recebimento_item where tenant_id=@t and recebimento_id=@id and quantidade_conferencia>0)",new{t=x.TenantId,id},tx,cancellationToken:ct)))throw new InvalidOperationException("Ainda existem quantidades em conferência; nenhuma alteração foi aplicada.");
  var hasRejected=await c.ExecuteScalarAsync<bool>(new CommandDefinition("select exists(select 1 from sigov.compras_empresarial_recebimento_item where tenant_id=@t and recebimento_id=@id and quantidade_rejeitada>0)",new{t=x.TenantId,id},tx,cancellationToken:ct));
  var hasAccepted=await c.ExecuteScalarAsync<bool>(new CommandDefinition("select exists(select 1 from sigov.compras_empresarial_recebimento_item where tenant_id=@t and recebimento_id=@id and quantidade_aceita>0)",new{t=x.TenantId,id},tx,cancellationToken:ct));
  var status=hasRejected?"COM_DIVERGENCIA":"CONCLUIDO";var resultado=hasRejected?(!hasAccepted?"RECUSADO":"REPROVADO_PARCIAL"):"APROVADO";
  var updated=await c.ExecuteAsync(new CommandDefinition("update sigov.compras_empresarial_recebimento set status=@status,resultado_inspecao=@resultado,inspecao_hash=@commandHash,version=version+1,updated_at=now(),updated_by=@user,correlation_id=@corr where tenant_id=@t and id=@id and version=@version;insert into sigov.compras_empresarial_recebimento_evento(tenant_id,recebimento_id,tipo,detalhes,usuario_id,correlation_id) values(@t,@id,'INSPECAO_CONCLUIDA',jsonb_build_object('status',@status,'justificativa',@justificativa),@usuario,@corr)",new{t=x.TenantId,id,status,resultado,commandHash,version=r.Version,user=x.UsuarioId.ToString(),usuario=x.UsuarioId,corr=x.CorrelationId,justificativa=r.Justificativa?.Trim()},tx,cancellationToken:ct));
  if(updated!=2)throw new InvalidOperationException("Conflito ao concluir a conferência; nenhuma alteração foi aplicada.");
  var usuarioNucleo = await c.QuerySingleOrDefaultAsync<long?>(new CommandDefinition("select id from sigov.usuario where md5('sigov:usuario:'||id::text)::uuid=@us limit 1", new { us = x.UsuarioId }, tx, cancellationToken: ct));
  var closed=await c.ExecuteAsync(new CommandDefinition(@"with atualizada as (
update sigov.pendencia_operacional p set status='RESOLVIDA',resolved_at=now(),updated_at=now(),versao=versao+1
from sigov.enterprise_tenant_mapping m where m.enterprise_tenant_id=@t and m.ativo and p.tenant_id=m.core_tenant_id
and p.modulo='COMPRAS_EMPRESARIAIS' and p.tipo='CONFERENCIA_RECEBIMENTO' and p.entidade='compras_empresarial_recebimento'
and p.entidade_id=@id::text and p.status in('ABERTA','EM_TRATAMENTO') returning p.id,p.tenant_id,p.versao)
insert into sigov.governanca_ocorrencia_historico(tenant_id,ocorrencia_tipo,ocorrencia_id,evento,usuario_id,justificativa,dados_depois)
select tenant_id,'PENDENCIA',id,'RESOLVIDA_NA_ORIGEM',@usuario,@justificativa,jsonb_build_object('recebimento_id',@id,'status_recebimento',@status,'versao',versao) from atualizada",new{t=x.TenantId,id,usuario=usuarioNucleo,justificativa=r.Justificativa?.Trim(),status},tx,cancellationToken:ct));
  if(closed!=1)throw new InvalidOperationException("A pendência de conferência não estava disponível para encerramento; nenhuma alteração foi aplicada.");
  if(hasRejected)
  {
   var currentRejected=r.Itens.Where(i=>i.QuantidadeRejeitada>0).ToArray();
   if(currentRejected.Length>0&&string.IsNullOrWhiteSpace(r.Justificativa))throw new InvalidOperationException("A decisão rejeitada não possui motivo persistível; nenhuma alteração foi aplicada.");
   foreach(var rejected in currentRejected)
   {
    var existing=await c.QuerySingleOrDefaultAsync<DivergenciaExistente>(new CommandDefinition("select id,recebimento_id RecebimentoId,quantidade_rejeitada QuantidadeRejeitada,motivo from sigov.compras_empresarial_recebimento_divergencia where tenant_id=@t and recebimento_item_id=@item for update",new{t=x.TenantId,item=rejected.RecebimentoItemId},tx,cancellationToken:ct));
    var reason=r.Justificativa!.Trim();
    if(existing is not null){if(existing.RecebimentoId!=id||existing.QuantidadeRejeitada!=rejected.QuantidadeRejeitada||existing.Motivo!=reason)throw new InvalidOperationException("Já existe divergência incompatível para o item; nenhuma alteração foi aplicada.");continue;}
    var divOrigemId=await c.ExecuteScalarAsync<long?>(new CommandDefinition("select divergencia_origem_id from sigov.compras_empresarial_recebimento_item where tenant_id=@t and id=@item",new{t=x.TenantId,item=rejected.RecebimentoItemId},tx,cancellationToken:ct));
    var divergenceId=await c.ExecuteScalarAsync<long>(new CommandDefinition("insert into sigov.compras_empresarial_recebimento_divergencia(tenant_id,recebimento_id,recebimento_item_id,quantidade_rejeitada,motivo,divergencia_origem_id,created_by,updated_by,correlation_id) values(@t,@id,@item,@quantity,@reason,@divOrigem,@user,@user,@corr) returning id",new{t=x.TenantId,id,item=rejected.RecebimentoItemId,quantity=rejected.QuantidadeRejeitada,reason,divOrigem=divOrigemId,user=x.UsuarioId.ToString(),corr=x.CorrelationId},tx,cancellationToken:ct));
    await c.ExecuteAsync(new CommandDefinition("insert into sigov.compras_empresarial_recebimento_divergencia_evento(tenant_id,divergencia_id,tipo,detalhes,usuario_id,correlation_id) values(@t,@divergenceId,'ABERTA',jsonb_build_object('recebimento_item_id',@item,'quantidade_rejeitada',@quantity,'motivo',@reason),@usuario,@corr)",new{t=x.TenantId,divergenceId,item=rejected.RecebimentoItemId,quantity=rejected.QuantidadeRejeitada,reason,usuario=x.UsuarioId,corr=x.CorrelationId},tx,cancellationToken:ct));
   }
   if(await c.ExecuteScalarAsync<bool>(new CommandDefinition("select exists(select 1 from sigov.compras_empresarial_recebimento_item ri where ri.tenant_id=@t and ri.recebimento_id=@id and ri.quantidade_rejeitada>0 and not exists(select 1 from sigov.compras_empresarial_recebimento_divergencia d where d.tenant_id=ri.tenant_id and d.recebimento_id=ri.recebimento_id and d.recebimento_item_id=ri.id))",new{t=x.TenantId,id},tx,cancellationToken:ct)))throw new InvalidOperationException("Há rejeição histórica sem evidência de motivo. Regularize-a explicitamente antes de concluir; nenhuma alteração foi aplicada.");
   var opened=await c.ExecuteAsync(new CommandDefinition(@"insert into sigov.pendencia_operacional(tenant_id,modulo,recurso,tipo,entidade,entidade_id,gravidade,titulo,descricao,rota_acao,status)
select m.core_tenant_id,'COMPRAS_EMPRESARIAIS','RECEBIMENTO','TRATAMENTO_DIVERGENCIA','compras_empresarial_recebimento',@id::text,'ALTA','Tratar divergência de recebimento','A inspeção registrou itens rejeitados que exigem tratamento operacional.','/ComprasEmpresariais/Divergencias?recebimentoId='||@id::text,'ABERTA' from sigov.enterprise_tenant_mapping m where m.enterprise_tenant_id=@t and m.ativo on conflict(tenant_id,modulo,tipo,entidade,entidade_id) where status in('ABERTA','EM_TRATAMENTO') do update set rota_acao=excluded.rota_acao,updated_at=now()",new{t=x.TenantId,id},tx,cancellationToken:ct));
   if(opened!=1)throw new InvalidOperationException("A pendência de tratamento da divergência não pôde ser criada; nenhuma alteração foi aplicada.");
  }
  var persisted=await c.QuerySingleAsync<RecebimentoExistente>(new CommandDefinition("select id,status from sigov.compras_empresarial_recebimento where tenant_id=@t and id=@id",new{t=x.TenantId,id},tx,cancellationToken:ct));await tx.CommitAsync(ct);return new(persisted.Id,persisted.Status,false);
 }
 private static string InspectionHash(ConcluirInspecaoRequest request)
 {
  var normalized=request.Version.ToString(CultureInfo.InvariantCulture)+"|"+string.Join("|",request.Itens.OrderBy(i=>i.RecebimentoItemId).Select(i=>$"{i.RecebimentoItemId}:{i.QuantidadeAceita.ToString("0.####",CultureInfo.InvariantCulture)}:{i.QuantidadeRejeitada.ToString("0.####",CultureInfo.InvariantCulture)}"))+"|"+(request.Justificativa?.Trim()??string.Empty);
  return Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(normalized))).ToLowerInvariant();
 }
 private static string? Clean(string? value)=>string.IsNullOrWhiteSpace(value)?null:value.Trim();
